export const BATCH_GLOSSARY=freeze({whole:'The whole thing we are talking about.',batch:'Both jars on one recipe card, enough for two guests.',copy:'One more whole batch with the same amounts.',guest:'One place at the table.',volume:'How much liquid is in a jug or jar right now, in mL.',capacity:'The most a jug or jar can hold. Here that is 500 mL.'});
export const BATCH_TEACHING=freeze({whole:'The same loaf can be cut into two equal halves, or four equal quarters. One quarter is one equal share of that loaf. Now the whole is a recipe card. One card is 100 mL cloud-water and 150 mL star-water, enough for two guests. The two jars hold different amounts.',base:'Keep each number with its thing. 100 mL goes with cloud-water. 150 mL goes with star-water. One card is for two guests.',copies:'Repeat the whole card. Each card adds two guests and both jars. Taking a card away takes away that whole group. Three copies mean three times each amount on the card.',contrast:'Two copies use 200 mL cloud-water and 300 mL star-water. Add 100 mL to both jars and you get 300 and 400. Add one whole batch and you get 300 and 450. Look at the star-water jar to see the difference.',reference:'Two matching cards serve four guests with 200 mL cloud-water and 300 mL star-water. Find the amounts on one card. One card is for two guests.',scale:'The jug has ten equal 50 mL spaces. Read how much is in the jug now. The recipe amount is a different question. If the jug shows 300 mL, then 300 mL is the right reading, even when the recipe wants 200 mL.',message:'Name the place, the guests and both amounts in mL. Choose each part from its list.',ending:'Your tray steams gently on the long table. Someone has already saved a seat for it.'});
